import time
import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

PIN_LIST = [2, 3, 4]
INTERVAL_SECONDS = 60

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    for pin in PIN_LIST:
        try:
            dev = OutputDevice(pin)
            devices.append(dev)
            print(f"GPIO {pin} initialized as output.")
        except GPIOZeroError as e:
            print(f"Error: Failed to initialize GPIO {pin}: {e}", file=sys.stderr)
            for d in devices:
                d.close()
            sys.exit(1)
        except Exception as e:
            print(f"Unexpected error on GPIO {pin}: {e}", file=sys.stderr)
            for d in devices:
                d.close()
            sys.exit(1)

    try:
        while _running:
            for dev in devices:
                try:
                    dev.off()
                except DeviceClosed:
                    pass
                except Exception as e:
                    print(f"Warning: Failed to reset GPIO {dev.pin}: {e}", file=sys.stderr)
            print("All outputs set to LOW.")
            for _ in range(INTERVAL_SECONDS):
                if not _running:
                    break
                time.sleep(1)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

