import time
import signal
import sys
from gpiozero import PWMOutputDevice

PINS = [1, 2, 3, 4]
PERIOD = 0.1

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

devices = []
for pin in PINS:
    try:
        dev = PWMOutputDevice(pin, frequency=1000, initial_value=0.0)
        devices.append(dev)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{pin}: {e}", file=sys.stderr)
        for d in devices:
            d.close()
        sys.exit(1)

try:
    while running:
        for dev in devices:
            try:
                val = 0.5 + (time.time() % 1.0) * 0.2
                if not (0.0 <= val <= 1.0):
                    raise ValueError("value out of range")
                dev.value = val
            except Exception as e:
                print(f"Invalid reading on GPIO{dev.pin}: {e}", file=sys.stderr)
                dev.value = 0.0
        time.sleep(PERIOD)
finally:
    for dev in devices:
        dev.value = 0.0
        dev.close()
    print("GPIO cleanup completed.")

