import serial
import time
import sys
import signal

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 115200
READ_TIMEOUT_S = 1.0
RETRY_DELAY_S = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_serial_data(ser):
    """Read a line from the serial port and return it, or None on timeout/error."""
    try:
        raw = ser.readline()
        if not raw:
            return None
        return raw.decode("utf-8", errors="replace").strip()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT_S,
        )
        print(f"Connected to {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl+C to stop.")

        while _running:
            data = read_serial_data(ser)
            if data is not None:
                print(data)
            if _running:
                time.sleep(RETRY_DELAY_S)

    except serial.SerialException as e:
        print(f"Serial port error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PIN = 17

def main() -> int:
    try:
        out = OutputDevice(PIN, active_high=True, initial_value=False)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO {PIN}: {exc}", file=sys.stderr)
        return 1

    try:
        out.on()
        print(f"GPIO {PIN} set to HIGH")
    except GPIOZeroError as exc:
        print(f"Failed to set GPIO {PIN} HIGH: {exc}", file=sys.stderr)
        return 1

    try:
        out.off()
        print(f"GPIO {PIN} set to LOW")
    except GPIOZeroError as exc:
        print(f"Failed to set GPIO {PIN} LOW: {exc}", file=sys.stderr)
        return 1

    return 0

def _handle_sigint(signum, frame):
    raise KeyboardInterrupt

signal.signal(signal.SIGINT, _handle_sigint)

if __name__ == "__main__":
    try:
        sys.exit(main())
    finally:
        # gpiozero closes the pin automatically on garbage collection,
        # but we explicitly close to release the hardware promptly.
        try:
            OutputDevice.close_all()
        except Exception:
            pass

