SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 115200
READ_INTERVAL_SECONDS = 5

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_sensor_data(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        return raw.decode("utf-8", errors="replace").strip()
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None

def check_data_validity(data):
    if not data:
        return False
    return True

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")

        while running:
            data = read_sensor_data(ser)
            if data is None:
                print("No data received (device may be disconnected).", file=sys.stderr)
                break

            if not check_data_validity(data):
                print(f"Invalid data received: {data!r}", file=sys.stderr)
                break

            print(f"Sensor Data: {data}")

            if running:
                time.sleep(READ_INTERVAL_SECONDS)

    except serial.SerialException as e:
        print(f"Error: Could not open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

