import time
import signal
import sys
from smbus2 import SMBus

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B

running = True

def handle_sigint(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_sigint)

def read_mpu6050(bus):
    try:
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0)
        time.sleep(0.1)
        data = bus.read_i2c_block_data(MPU6050_ADDR, ACCEL_XOUT_H, 6)
        x = (data[0] << 8) | data[1]
        y = (data[2] << 8) | data[3]
        z = (data[4] << 8) | data[5]
        if x >= 0x8000:
            x -= 0x10000
        if y >= 0x8000:
            y -= 0x10000
        if z >= 0x8000:
            z -= 0x10000
        return x, y, z
    except OSError:
        return None, None, None

def main():
    bus = None
    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            x, y, z = read_mpu6050(bus)
            if x is None:
                print("Error: MPU6050 not detected at address 0x68", file=sys.stderr)
                sys.exit(1)
            print(f"Accel X: {x}, Y: {y}, Z: {z}")
            time.sleep(0.05)
    finally:
        if bus is not None:
            bus.close()

if __name__ == "__main__":
    main()

