import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

# HC-SR04 trigger -> GPIO 17, echo -> GPIO 22 (BCM numbering)
TRIGGER_PIN = 17
ECHO_PIN = 22

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = None
    try:
        sensor = DistanceSensor(
            echo=ECHO_PIN,
            trigger=TRIGGER_PIN,
            max_distance=4.0,
            threshold_distance=0.02,
        )
    except GPIOZeroError as exc:
        print(f"Failed to initialize HC-SR04 on trigger=GPIO{TRIGGER_PIN}, echo=GPIO{ECHO_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for cycle in range(1, 6):
            if not _running:
                print("Interrupted by signal; exiting early.")
                break

            try:
                distance_m = sensor.distance
            except DeviceClosed:
                print("Sensor device closed unexpectedly; aborting cycle.", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Distance read error: {exc}", file=sys.stderr)
                break

            if distance_m is None:
                print(f"Cycle {cycle}: No response from HC-SR04 (timeout or disconnected).")
            else:
                print(f"Cycle {cycle}: Distance = {distance_m * 100:.1f} cm")

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while slept < 50.0 and _running:
                time.sleep(0.1)
                slept += 0.1

    finally:
        if sensor is not None:
            try:
                sensor.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

