import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [12, 20, 21]
PERIOD = 0.03

running = True

def _handle_signal(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = PWMOutputDevice(pin, frequency=1000, initial_value=0.0)
                devices.append(dev)
                print(f"GPIO {pin} -> {dev.value:.4f}", flush=True)
            except GPIOZeroError as e:
                print(f"Error: failed to initialize GPIO {pin}: {e}", file=sys.stderr)
