    try:
        while running:
            for dev in devices:
                dev.value = 0.5
            time.sleep(PERIOD)
            for dev in devices:
                dev.value = 0.0
            time.sleep(PERIOD)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.value = 0.0
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.", flush=True)
