        print(f"Error: failed to initialize GPIO pins {PIN_A}/{PIN_B}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                state_a = dev_a.value
                state_b = dev_b.value
            except DeviceClosed:
                print("Error: device closed unexpectedly.", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Error reading GPIO: {exc}", file=sys.stderr)
                break

            if not (0 <= state_a <= 1 and 0 <= state_b <= 1):
                print("Error: invalid GPIO state reading.", file=sys.stderr)
                break

            print(f"GPIO {PIN_A} = {state_a}, GPIO {PIN_B} = {state_b}")

            if _running:
                time.sleep(INTERVAL_S)
    finally:
        for dev in (dev_a, dev_b):
            try:
                dev.close()
            except Exception:
                pass


