import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
READ_INTERVAL_SECONDS = 1
NUM_READINGS = 3

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def exchange_data(ser):
    """Read one line from the serial port and print it."""
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return False
    if not raw:
        print("No data received (timeout).", file=sys.stderr)
        return False
    line = raw.decode('ascii', errors='replace').strip()
    if line:
        print(f"Received: {line}")
    return True

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Failed to open {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        readings_done = 0
        while readings_done < NUM_READINGS and _running:
            if not exchange_data(ser):
                break
            readings_done += 1
            if readings_done < NUM_READINGS and _running:
                time.sleep(READ_INTERVAL_SECONDS)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Serial port closed.")

if __name__ == "__main__":
    main()

