import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

# HC-SR04 pins (BCM numbering)
SENSOR_PINS = [17, 18, 22, 23]

# Graceful shutdown flag
_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    # Install signal handlers for clean exit on Ctrl-C / SIGTERM
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize one DistanceSensor per pin; catch missing hardware / bus errors
    sensors = []
    for pin in SENSOR_PINS:
        try:
            sensor = DistanceSensor(pin, max_distance=4.0, threshold_distance=0.02)
            sensors.append(sensor)
        except GPIOZeroError as exc:
            print(f"Failed to initialize HC-SR04 on GPIO{pin}: {exc}", file=sys.stderr)
            # Clean up anything we already opened
            for s in sensors:
                try:
                    s.close()
                except DeviceClosed:
                    pass
            sys.exit(1)

    try:
        while _running:
            readings = []
            for sensor in sensors:
                try:
                    distance = sensor.distance
                    if distance is None or distance < 0.02 or distance > 4.0:
                        readings.append(f"GPIO{sensor.pin}: out of range ({distance:.3f} m)")
                    else:
                        readings.append(f"GPIO{sensor.pin}: {distance:.3f} m")
                except DeviceClosed:
                    readings.append(f"GPIO{sensor.pin}: closed")
                    break

            print(" | ".join(readings))
            sys.stdout.flush()

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < 5.0:
                time.sleep(0.1)
                slept += 0.1

    finally:
        # Release every sensor deterministically
        for sensor in sensors:
            try:
                sensor.close()
            except DeviceClosed:
                pass
        print("\nCleanup complete. Exiting.")


if __name__ == "__main__":
    main()

