_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate):
    try:
        ser = serial.Serial(port, baudrate, timeout=1)
        return ser
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}", file=sys.stderr)
        return None

def read_sensor_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
