import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

PCA9685_ADDR = 0x40
REG_MODE1 = 0x00
REG_PRESCALE = 0xFE
REG_LED0_ON_L = 0x06

MODE1_SLEEP = 0x10
MODE1_AI = 0x20
MODE1_RESTART = 0x80

VALID_PRESCALE = {4, 5, 6, 7, 8, 9}

running = True


def signal_handler(signum, frame):
    global running
    running = False


def read_pca9685(bus, address):
    """Read MODE1 and PRESCALE from the PCA9685; return (mode1, prescale)."""
    try:
        mode1 = bus.read_byte_data(address, REG_MODE1)
        prescale = bus.read_byte_data(address, REG_PRESCALE)
        return mode1, prescale
    except OSError as exc:
        raise RuntimeError(f"I2C read failed: {exc}") from exc


def set_pca9685_mode1(bus, address, mode1):
    """Write MODE1 to the PCA9685."""
    try:
        bus.write_byte_data(address, REG_MODE1, mode1)
    except OSError as exc:
        raise RuntimeError(f"I2C write failed: {exc}") from exc


def set_pca9685_prescale(bus, address, prescale):
    """Write PRESCALE to the PCA9685."""
    try:
        bus.write_byte_data(address, REG_PRESCALE, prescale)
    except OSError as exc:
        raise RuntimeError(f"I2C write failed: {exc}") from exc


def validate_prescale(prescale):
    if not isinstance(prescale, int) or not 4 <= prescale <= 255:
        raise ValueError(f"Invalid prescale {prescale!r}")
    if prescale not in VALID_PRESCALE:
        raise ValueError(f"Non-standard prescale {prescale!r}")


def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    try:
        bus = SMBus(1)
    except OSError as exc:
        print(f"Error: cannot open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            mode1, prescale = read_pca9685(bus, PCA9685_ADDR)
        except RuntimeError as exc:
            print(f"Error: PCA9685 not found at 0x{PCA9685_ADDR:02X}: {exc}", file=sys.stderr)
            sys.exit(1)

        if not (mode1 & MODE1_RESTART):
            print("Error: PCA9685 is in sleep mode; write MODE1_RESTART first.", file=sys.stderr)
            sys.exit(1)

        validate_prescale(prescale)
        print(f"PCA9685 found, mode1=0x{mode1:02X}, prescale={prescale}")

        while running:
            try:
                set_pca9685_mode1(bus, PCA9685_ADDR, mode1 | MODE1_SLEEP)
                time.sleep(0.15)
                if not running:
                    break
                set_pca9685_mode1(bus, PCA9685_ADDR, mode1)
                print(f"{mode1 & 0xFF:02X}  {prescale}")
            except RuntimeError as exc:
                print(f"Warning: read failed: {exc}", file=sys.stderr)
                time.sleep(0.15)
    finally:
        if bus is not None:
            try:
                set_pca9685_mode1(bus, PCA9685_ADDR, mode1 | MODE1_SLEEP)
            except RuntimeError:
                pass
            bus.close()
            print("I2C bus closed.")


if __name__ == "__main__":
    main()

