import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

INA219_ADDR = 0x1d
REG_CONFIG = 0x00
REG_SHUNT_VOLTAGE = 0x01
REG_BUS_VOLTAGE = 0x02
REG_POWER = 0x03
REG_CURRENT = 0x04
REG_CALIBRATION = 0x05

CONFIG_DEFAULT = 0x0000
CONFIG_BRNG_16V = 0x0004
CONFIG_BRNG_32V = 0x0008
CONFIG_128US = 0x0020
CONFIG_BRNG_AND_128US = CONFIG_BRNG_16V | CONFIG_128US


def ina219_init(bus, address):
    try:
        bus.write_word_data(address, REG_CONFIG, CONFIG_BRNG_AND_128US)
        bus.write_word_data(address, REG_CALIBRATION, 0x0000)
        return True
    except OSError:
        return False


def ina219_read_config(bus, address):
    try:
        return bus.read_word_data(address, REG_CONFIG)
    except OSError:
        return None


def ina219_read_shunt_voltage(bus, address):
    try:
        data = bus.read_word_data(address, REG_SHUNT_VOLTAGE)
        return data << 8 | (data & 0xFF00) >> 8
    except OSError:
        return None


def ina219_read_bus_voltage(bus, address):
    try:
        data = bus.read_word_data(address, REG_BUS_VOLTAGE)
        return data << 8 | (data & 0xFF00) >> 8
    except OSError:
        return None


def ina219_read_power(bus, address):
    try:
        data = bus.read_word_data(address, REG_POWER)
        return data << 8 | (data & 0xFF00) >> 8
    except OSError:
        return None


def ina219_read_current(bus, address):
    try:
        data = bus.read_word_data(address, REG_CURRENT)
        return data << 8 | (data & 0xFF00) >> 8
    except OSError:
        return None


def ina219_print_reading(bus, address):
    config = ina219_read_config(bus, address)
    if config is None:
        print("Error: INA219 not responding (no config read).", file=sys.stderr)
        return False
    shunt = ina219_read_shunt_voltage(bus, address)
    bus_v = ina219_read_bus_voltage(bus, address)
    power = ina219_read_power(bus, address)
    curr = ina219_read_current(bus, address)
    if shunt is None or bus_v is None or power is None or curr is None:
        print("Error: Failed to read one or more registers.", file=sys.stderr)
        return False
    print(f"Shunt Voltage: {shunt} mV")
    print(f"Bus Voltage: {bus_v} mV")
    print(f"Power: {power} uW")
    print(f"Current: {curr} uA")
    return True


_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: Cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        if not ina219_init(bus, INA219_ADDR):
            print(f"Error: INA219 not found at address 0x{INA219_ADDR:02X}.", file=sys.stderr)
            sys.exit(1)

        readings_taken = 0
        while _running and readings_taken < 5:
            ina219_print_reading(bus, INA219_ADDR)
            readings_taken += 1
            if _running and readings_taken < 5:
                time.sleep(1)

        if not _running:
            print("\nInterrupted by user.", file=sys.stderr)
            sys.exit(130)

    except OSError as e:
        print(f"Error: I2C communication failure: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if bus is not None:
            bus.close()


if __name__ == "__main__":
    main()

import time
import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

PIN = 17
INTERVAL = 60

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

try:
    device = OutputDevice(PIN)
except GPIOZeroError as e:
    print(f"Error: could not initialize GPIO {PIN} as output: {e}", file=sys.stderr)
    sys.exit(1)
except Exception as e:
    print(f"Unexpected error initializing GPIO {PIN}: {e}", file=sys.stderr)
    sys.exit(1)

try:
    while running:
        try:
            device.on()
            print(f"GPIO {PIN} -> HIGH")
        except DeviceClosed:
            print("Error: device was closed unexpectedly.", file=sys.stderr)
            break
        except Exception as e:
            print(f"Error writing to GPIO {PIN}: {e}", file=sys.stderr)
            break

        for _ in range(INTERVAL):
            if not running:
                break
            time.sleep(1)

        try:
            device.off()
            print(f"GPIO {PIN} -> LOW")
        except DeviceClosed:
            print("Error: device was closed unexpectedly.", file=sys.stderr)
            break
        except Exception as e:
            print(f"Error writing to GPIO {PIN}: {e}", file=sys.stderr)
            break

        for _ in range(INTERVAL):
            if not running:
                break
            time.sleep(1)

finally:
    try:
        device.close()
    except Exception:
        pass
    print("GPIO cleanup done.")

