import signal
import sys
import time

import board
import adafruit_dht

PINS = [board.D4, board.D7, board.D11, board.D17]

running = True

def _handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)

devices = {}
for pin in PINS:
    try:
        devices[pin] = adafruit_dht.DHT22(pin, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialise DHT22 on {pin}: {exc}", file=sys.stderr)

try:
    while running:
        for pin, dev in devices.items():
            if not running:
                break
            try:
                temp = dev.temperature
                hum = dev.humidity
                if temp is None or hum is None:
                    print(f"Pin {pin}: no data", file=sys.stderr)
                else:
                    print(f"Pin {pin}: {temp:.1f}C  {hum:.1f}%")
            except RuntimeError as exc:
                # DHT22 checksum / timing glitches are common; report and continue.
                print(f"Pin {pin}: read error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Pin {pin}: unexpected error: {exc}", file=sys.stderr)

        if running:
            time.sleep(5)
finally:
    for dev in devices.values():
        try:
            dev.exit()
        except Exception:
            pass
    print("Clean exit.")

