import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B
ACCEL_SCALE = 2.0 / 16384.0

running = True

def handle_sigint(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_sigint)

def read_word(bus, addr, reg):
    msg_w = i2c_msg.write(addr, [reg])
    msg_r = i2c_msg.read(addr, 2)
    bus.i2c_rdwr(msg_w, msg_r)
    raw = (msg_r.buf[0] << 8) | msg_r.buf[1]
    if raw & 0x8000:
        raw -= 0x10000
    return raw

def main():
    bus = None
    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0)
        except OSError as e:
            print(f"Error: MPU6050 not responding at 0x{MPU6050_ADDR:02X}: {e}", file=sys.stderr)
            sys.exit(1)

        for i in range(3):
            if not running:
                break
            try:
                x = read_word(bus, MPU6050_ADDR, ACCEL_XOUT_H)
                value = x * ACCEL_SCALE
                if not (-1.0 <= value <= 1.0):
                    print(f"Reading {i+1}: value {value:.6f} out of expected range [-1, 1]", file=sys.stderr)
                else:
                    print(f"Reading {i+1}: {value:.6f}")
            except OSError as e:
                print(f"Error: I2C read failed on reading {i+1}: {e}", file=sys.stderr)
                sys.exit(1)
            time.sleep(0.1)
    finally:
        if bus is not None:
            bus.close()

