import time
import signal
import sys
import board
import adafruit_dht

# Global sensor list for cleanup
_sensors = []

def cleanup(signum=None, frame=None):
    """Release all DHT22 resources."""
    for s in _sensors:
        try:
            s.exit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def main():
    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize DHT22 sensors on all supported BCM pins
    pins = [board.D4, board.D17, board.D18, board.D22, board.D23, board.D27]
    for pin in pins:
        try:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            _sensors.append(sensor)
        except Exception as e:
            print(f"Failed to initialize DHT22 on {pin}: {e}", file=sys.stderr)

    if not _sensors:
        print("No DHT22 sensors initialized. Exiting.", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        for i in range(3):
            print(f"\n--- Cycle {i + 1} ---")
            for idx, sensor in enumerate(_sensors):
                try:
                    temp = sensor.temperature
                    hum = sensor.humidity
                    if temp is not None and hum is not None:
                        print(f"  Pin {pins[idx]}: {temp:.1f}C, {hum:.1f}%")
                    else:
                        print(f"  Pin {pins[idx]}: read failed (None)")
                except RuntimeError as e:
                    # DHT22 checksum or timing errors are common; log and continue
                    print(f"  Pin {pins[idx]}: read error: {e}")
                except Exception as e:
                    print(f"  Pin {pins[idx]}: unexpected error: {e}", file=sys.stderr)

            if i < 2:
                time.sleep(5)

    finally:
        cleanup()

if __name__ == "__main__":
    main()

