import time
import signal
import sys
import board
import adafruit_dht

# Global sensor handle so the signal handler can release it.
_sensor = None
_running = True

def _cleanup():
    """Release the sensor if it was created."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None

def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False

def main():
    global _sensor

    # Register signal handlers for clean exit on Ctrl-C or kill.
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize the DHT22 on GPIO 4, 17, and 27 (BCM numbering).
    # board.D4, board.D17, board.D27 map to BCM 4, 17, 27 respectively.
    pin_map = {4: board.D4, 17: board.D17, 27: board.D27}
    try:
        for pin in pin_map:
            _sensor = adafruit_dht.DHT22(pin_map[pin], use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        while _running:
            for pin in pin_map:
                try:
                    temp = _sensor.temperature
                    hum = _sensor.humidity
                    if temp is not None and hum is not None:
                        print(f"Pin {pin}: Temp={temp:.1f}C  Hum={hum:.1f}%", flush=True)
                    else:
                        print(f"Pin {pin}: Read failed (None)", flush=True)
                except RuntimeError as e:
                    # DHT22 checksum or timing errors are common; report and continue.
                    print(f"Pin {pin}: Read error: {e}", flush=True)
                except Exception as e:
                    print(f"Pin {pin}: Unexpected error: {e}", flush=True)

            # Sleep in small increments so signals are caught promptly.
            slept = 0.0
            while _running and slept < 1.0:
                time.sleep(0.05)
                slept += 0.05
    finally:
        _cleanup()

if __name__ == "__main__":
    main()

