import time
import signal
import sys
from smbus2 import SMBus

BMP280_ADDR = 0x76
CHIP_ID_REG = 0xD0
EXPECTED_CHIP_ID = 0x58

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

def read_chip_id(bus):
    chip_id = bus.read_byte_data(BMP280_ADDR, CHIP_ID_REG)
    if chip_id != EXPECTED_CHIP_ID:
        raise RuntimeError(
            f"Invalid chip ID: 0x{chip_id:02X} (expected 0x{EXPECTED_CHIP_ID:02X})"
        )

def read_raw_temp(bus):
    data = bus.read_i2c_block_data(BMP280_ADDR, 0x1E, 3)
    return (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)

def read_raw_pressure(bus):
    data = bus.read_i2c_block_data(BMP280_ADDR, 0x1E, 3)
    return (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)

def read_raw_humidity(bus):
    data = bus.read_i2c_block_data(BMP280_ADDR, 0x1E, 3)
    return (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)

def read_temperature(bus):
    raw = read_raw_temp(bus)
    if raw & 0x80000:
        raw -= 1 << 20
    return raw / 100.0

def read_pressure(bus):
    raw = read_raw_pressure(bus)
    if raw & 0x80000:
        raw -= 1 << 20
    return raw / 100.0

def read_humidity(bus):
    raw = read_raw_humidity(bus)
    if raw & 0x80000:
        raw -= 1 << 20
    return raw / 1024.0

def main():
    bus = None
    try:
        bus = SMBus(1)
        read_chip_id(bus)
        print("BMP280 detected at 0x76")

        for i in range(2):
            if not running:
                break
            try:
                temp = read_temperature(bus)
                pressure = read_pressure(bus)
                humidity = read_humidity(bus)
                print(f"Reading {i + 1}: T={temp:.2f} C  P={pressure:.2f} hPa  H={humidity:.2f} %")
            except Exception as e:
                print(f"Reading {i + 1} failed: {e}", file=sys.stderr)
            if i == 0 and running:
                time.sleep(1)

    except Exception as e:
        print(f"Fatal: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if bus is not None:
            bus.close()

if __name__ == "__main__":
    main()

