import time
import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

PIN_A = 17
PIN_B = 18
INTERVAL_S = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        dev_a = OutputDevice(PIN_A)
        dev_b = OutputDevice(PIN_B)
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize GPIO pins {PIN_A}/{PIN_B}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: unexpected initialization failure: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                state_a = dev_a.value
                state_b = dev_b.value
            except DeviceClosed:
                print("Error: device closed unexpectedly.", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Error: GPIO read failure: {exc}", file=sys.stderr)
                break

            if not (state_a in (0, 1) and state_b in (0, 1)):
                print(f"Error: invalid reading ({state_a}/{state_b}); skipping cycle.", file=sys.stderr)
                time.sleep(INTERVAL_S)
                continue

            print(f"GPIO {PIN_A}={state_a}  GPIO {PIN_B}={state_b}")
            time.sleep(INTERVAL_S)
    finally:
        for dev in (dev_a, dev_b):
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

