import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B

running = True

def handle_sigint(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_sigint)

def read_word(bus, addr, reg):
    msg_w = i2c_msg.write(addr, [reg])
    msg_r = i2c_msg.read(addr, 2)
    bus.i2c_rdwr(msg_w, msg_r)
    raw = list(msg_r)
    return (raw[0] << 8) | raw[1]

def main():
    bus = None
    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0)
        except OSError as e:
            print(f"Error: MPU6050 not responding at 0x{MPU6050_ADDR:02X}: {e}", file=sys.stderr)
            sys.exit(1)

        for i in range(5):
            if not running:
                break
            try:
                x = read_word(bus, MPU6050_ADDR, ACCEL_XOUT_H)
                print(f"Reading {i+1}: accel_x = {x}")
            except OSError as e:
                print(f"Error reading MPU6050: {e}", file=sys.stderr)
                sys.exit(1)
            time.sleep(0.1)
    finally:
        if bus is not None:
            bus.close()

if __name__ == "__main__":
    main()

import time
import signal
import sys
import board
import adafruit_dht

# Global sensor handle so the signal handler can release it.
_sensor = None

def cleanup(signum=None, frame=None):
    """Release the sensor on exit or signal."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None
    if signum is not None:
        sys.exit(0)

def main():
    global _sensor

    # Register signal handlers for clean shutdown.
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize the DHT11 on GPIO 17 (BCM) using adafruit-circuitpython-dht.
    try:
        _sensor = adafruit_dht.DHT11(board.D17, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 on GPIO 17: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for cycle in range(5):
            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is None or humidity is None:
                    print("Sensor returned None (check wiring or device presence).", file=sys.stderr)
                    break

                print(f"Cycle {cycle + 1}: Temp = {temperature:.1f} C  Humidity = {humidity:.1f} %")

            except RuntimeError as e:
                # DHT11 checksum or timing errors are common; report and continue.
                print(f"Cycle {cycle + 1} read error: {e}", file=sys.stderr)
                break

            time.sleep(0.5)

    except Exception as e:
        print(f"Unexpected error during sensor loop: {e}", file=sys.stderr)

    finally:
        cleanup()

if __name__ == "__main__":
    main()

