import time
import signal
import sys
from smbus2 import SMBus

INA219_ADDRESS = 0x17
REG_CONFIG = 0x00
REG_SHUNT_VOLTAGE = 0x01
REG_BUS_VOLTAGE = 0x02
REG_POWER = 0x03
REG_CURRENT = 0x04
REG_CALIBRATION = 0x05

CONFIG_DEFAULT = 0x0000
CONFIG_BRNG_16V = 0x0020
CONFIG_BRNG_32V = 0x0040
CONFIG_128US = 0x0001
CONFIG_BRNG_16V_128US = (CONFIG_BRNG_16V | CONFIG_128US)
CONFIG_BRNG_32V_128US = (CONFIG_BRNG_32V | CONFIG_128US)


def ina219_init(bus, address):
    try:
        bus.write_word_data(address, REG_CONFIG, CONFIG_DEFAULT)
        bus.write_word_data(address, REG_CALIBRATION, 0x0000)
        return True
    except OSError:
        return False


def ina219_read_config(bus, address):
    try:
        return bus.read_word_data(address, REG_CONFIG)
    except OSError:
        return None


def ina219_read_shunt_voltage(bus, address):
    try:
        raw = bus.read_word_data(address, REG_SHUNT_VOLTAGE)
        if raw & 0x8000:
            raw -= 0x10000
        return raw * 0.125
    except OSError:
        return None


def ina219_read_bus_voltage(bus, address):
    try:
        raw = bus.read_word_data(address, REG_BUS_VOLTAGE)
        if raw & 0x8000:
            raw -= 0x10000
        return raw * 0.04096
    except OSError:
        return None


def ina219_read_power(bus, address):
    raw = bus.read_word_data(address, REG_POWER)
    if raw & 0x8000:
        raw -= 0x10000
    return raw * 0.0625


def ina219_read_current(bus, address):
    raw = bus.read_word_data(address, REG_CURRENT)
    if raw & 0x8000:
        raw -= 0x10000
    return raw * 0.0005


def main():
    running = True

    def handle_signal(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    bus = None
    try:
        bus = SMBus(1)
        if not ina219_init(bus, INA219_ADDRESS):
            print(f"Error: INA219 not found at address 0x{INA219_ADDRESS:02X}", file=sys.stderr)
            sys.exit(1)

        while running:
            config = ina219_read_config(bus, INA219_ADDRESS)
            if config is None:
                print("Error: INA219 communication lost", file=sys.stderr)
                break

            shunt_voltage = ina219_read_shunt_voltage(bus, INA219_ADDRESS)
            bus_voltage = ina219_read_bus_voltage(bus, INA219_ADDRESS)
            power = ina219_read_power(bus, INA219_ADDRESS)
            current = ina219_read_current(bus, INA219_ADDRESS)

            if shunt_voltage is None or bus_voltage is None or power is None or current is None:
                print("Error: Failed to read INA219 data", file=sys.stderr)
                break

            print(f"Shunt Voltage: {shunt_voltage:.3f} mV")
            print(f"Bus Voltage: {bus_voltage:.3f} V")
            print(f"Power: {power:.3f} mW")
            print(f"Current: {current:.3f} mA")
            print("-" * 40)

            time.sleep(2)

    except OSError as e:
        print(f"I2C bus error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if bus is not None:
            bus.close()


if __name__ == "__main__":
    main()

