import signal
import sys
import time

from smbus2 import SMBus

I2C_BUS = 1
BMP280_ADDR = 0x76
CHIP_ID_REG = 0xD0
EXPECTED_CHIP_ID = 0x58

running = True


def handle_signal(signum, frame):
    global running
    running = False


def read_chip_id(bus):
    return bus.read_byte_data(BMP280_ADDR, CHIP_ID_REG)


def main():
    global running

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        chip_id = read_chip_id(bus)
    except OSError as e:
        print(f"Error: no device found at 0x{BMP280_ADDR:02X} on bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    if chip_id != EXPECTED_CHIP_ID:
        print(f"Error: unexpected chip ID 0x{chip_id:02X} (expected 0x{EXPECTED_CHIP_ID:02X})", file=sys.stderr)
        sys.exit(1)

    print(f"BMP280 detected at 0x{BMP280_ADDR:02X} (chip ID 0x{chip_id:02X})")

    try:
        while running:
            try:
                data = bus.read_i2c_block_data(BMP280_ADDR, 0xF7, 6)
                raw = (data[0] << 16) | (data[1] << 8) | data[2]
                ut = (data[3] << 16) | (data[4] << 8)
                vt = data[5]
                print(f"raw={raw} ut={ut} vt={vt}")
            except OSError as e:
                print(f"Warning: I2C read failed: {e}", file=sys.stderr)

            for _ in range(5):
                if not running:
                    break
                time.sleep(1)
    finally:
        if bus is not None:
            bus.close()


if __name__ == "__main__":
    main()

