import time
import signal
import sys
from gpiozero import DistanceSensor

# HC-SR04 configuration
TRIGGER_PIN = 17
ECHO_PIN = 18
MAX_DISTANCE_M = 1.0  # gpiozero expects meters; HC-SR04 max ~4 m

# Global sensor handle so the signal handler can release it
_sensor = None


def cleanup(signum=None, frame=None):
    """Release the sensor on exit or signal."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.close()
        except Exception:
            pass
        _sensor = None
    if signum is not None:
        sys.exit(0)


def main():
    global _sensor

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize the HC-SR04 sensor
    try:
        _sensor = DistanceSensor(
            echo=ECHO_PIN,
            trigger=TRIGGER_PIN,
            max_distance=MAX_DISTANCE_M,
        )
    except Exception as exc:
        print(f"Failed to initialize HC-SR04 on trigger={TRIGGER_PIN}, echo={ECHO_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for cycle in range(1, 11):
            try:
                distance_m = _sensor.distance
            except Exception as exc:
                # Device not responding or read failed
                print(f"Cycle {cycle}: read error ({exc}); skipping.")
                continue

            # HC-SR04 valid range is ~2 cm to 400 cm (20 m)
            if distance_m < 0.02 or distance_m > 4.0:
                print(f"Cycle {cycle}: out of valid range ({distance_m:.3f} m); skipping.")
                continue

            print(f"Cycle {cycle}: distance = {distance_m:.3f} m")
            time.sleep(0.1)

    except Exception as exc:
        print(f"Unexpected error during measurement loop: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

