import time
import signal
import sys
from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, BadPinFactory

# HC-SR04 pins (BCM numbering)
TRIG_PINS = [19, 20, 24, 25, 26]
ECHO_PINS = [10, 9, 11, 12, 13]

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    for sig in (signal.SIGINT, signal.SIGTERM):
        signal.signal(sig, _handle_signal)

    sensors = []
    try:
        for trig, echo in zip(TRIG_PINS, ECHO_PINS):
            try:
                sensor = DistanceSensor(echo=echo, trigger=trig, max_distance=4.0)
                sensors.append(sensor)
            except (BadPinFactory, GPIOZeroError) as e:
                print(f"Failed to initialize HC-SR04 on TRIG={trig}, ECHO={echo}: {e}", file=sys.stderr)
                return
    except Exception as e:
        print(f"Unexpected error during sensor initialization: {e}", file=sys.stderr)
        return

    try:
        while _running:
            readings = []
            for sensor in sensors:
                try:
                    distance = sensor.distance
                    if distance is not None:
                        readings.append(f"TRIG={sensor.trigger.pin}, ECHO={sensor.echo.pin}: {distance:.3f}m")
                except Exception as e:
                    readings.append(f"TRIG={sensor.trigger.pin}, ECHO={sensor.echo.pin}: error ({e})")

            print(" | ".join(readings))
            time.sleep(1)
    finally:
        for sensor in sensors:
            try:
                sensor.close()
            except Exception:
                pass
        print("\nGPIO resources released. Exiting.")

if __name__ == "__main__":
    main()

import time
import signal
import sys
from smbus2 import SMBus

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B
ACCEL_SCALE = 2.0 / 16384.0

running = True

def handle_sigint(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_sigint)

def read_word(bus, addr, reg):
    high = bus.read_byte_data(addr, reg)
    low = bus.read_byte_data(addr, reg + 1)
    val = (high << 8) | low
    if val >= 0x8000:
        val -= 0x10000
    return val

def main():
    global running
    bus = None
    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0)
        except OSError as e:
            print(f"Error: failed to wake MPU6050: {e}", file=sys.stderr)
            sys.exit(1)

        for i in range(8):
            if not running:
                break
            try:
                x = read_word(bus, MPU6050_ADDR, ACCEL_XOUT_H)
                if not (-32768 <= x <= 32767):
                    print(f"Reading {i}: value out of range", file=sys.stderr)
                    continue
                print(f"Reading {i}: x={x * ACCEL_SCALE:.4f} m/s^2")
            except OSError as e:
                print(f"Error: I2C read failed on reading {i}: {e}", file=sys.stderr)
                continue
            time.sleep(0.1)
    finally:
        if bus is not None:
            bus.close()

if __name__ == "__main__":
    main()

