import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _check_pin(pin: int, value: float) -> bool:
    """Return True if value is within the documented PWM range for *pin*."""
    if pin == 5 or pin == 6:
        return 0.0 <= value <= 1.0
    if pin == 13 or pin == 17 or pin == 27:
        return 0.0 <= value <= 1.0
    if pin == 18 or pin == 22:
        return 0.0 <= value <= 1.0
    if pin == 23 or pin == 24:
        return 0.0 <= value <= 1.0
    return False


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    for pin in PINS:
        try:
            dev = PWMOutputDevice(pin, initial_value=0.0, frequency=1000)
            devices.append(dev)
            print(f"GPIO {pin}: PWM initialized (0.0-1.0)", file=sys.stderr)
        except GPIOZeroError as exc:
            print(f"GPIO {pin}: init failed ({exc}), skipping", file=sys.stderr)
        except Exception as exc:
            print(f"GPIO {pin}: unexpected init error ({exc}), skipping", file=sys.stderr)

    if not devices:
        print("No PWM devices available; exiting.", file=sys.stderr)
        return 1

    try:
        while _running:
            for dev in devices:
                if not _running:
                    break
                try:
                    val = 0.5 + (time.time() % 1.0)
                    if not _check_pin(dev.pin.number, val):
                        raise ValueError(f"value {val} out of range for pin {dev.pin.number}")
                    dev.value = val
                except (DeviceClosed, GPIOZeroError) as exc:
                    print(f"GPIO {dev.pin.number}: write failed ({exc}), closing", file=sys.stderr)
                    try:
                        dev.close()
                    except Exception:
                        pass
                except Exception as exc:
                    print(f"GPIO {dev.pin.number}: write error ({exc}), closing", file=sys.stderr)
                    try:
                        dev.close()
                    except Exception:
                        pass

            if _running:
                time.sleep(1)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("All devices closed; exiting.", file=sys.stderr)

    return 0


if __name__ == "__main__":
    sys.exit(main())

