import signal
import sys
import time

from smbus2 import SMBus

INA219_ADDRESS = 0x17
REG_CONFIG = 0x00
REG_SHUNT_VOLTAGE = 0x01
REG_BUS_VOLTAGE = 0x02
REG_POWER = 0x03
REG_CURRENT = 0x04
REG_CALIBRATION = 0x05

CONFIG_DEFAULT = 0x0000
CONFIG_BRNG_16V = 0x0004
CONFIG_BRNG_32V = 0x0008
CONFIG_BRNG_64V = 0x000C
CONFIG_12BIT = 0x0020
CONFIG_BRNG_AND_12BIT = (CONFIG_BRNG_16V | CONFIG_BRNG_32V | CONFIG_BRNG_64V) | CONFIG_12BIT


class INA219:
    def __init__(self, bus_num=1, address=INA219_ADDRESS):
        self.address = address
        self.bus = SMBus(bus_num)
        self._configure(CONFIG_BRNG_AND_12BIT)

    def _configure(self, config):
        self.bus.write_word_data(self.address, REG_CONFIG, config)

    def _read_word(self, reg):
        return self.bus.read_word_data(self.address, reg)

    def _read_signed_word(self, reg):
        val = self._read_word(reg)
        if val >= 0x8000:
            val -= 0x10000
        return val

    def get_bus_voltage(self):
        return self._read_word(REG_BUS_VOLTAGE) * 0.001

    def get_shunt_voltage(self):
        return self._read_word(REG_SHUNT_VOLTAGE) * 0.001

    def get_power(self):
        return self._read_signed_word(REG_POWER)

    def get_current(self):
        return self._read_signed_word(REG_CURRENT)

    def close(self):
        self.bus.close()


def main():
    ina = INA219()
    running = True

    def handle_sigint(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, handle_sigint)

    try:
        while running:
            bus_v = ina.get_bus_voltage()
            shunt_v = ina.get_shunt_voltage()
            power = ina.get_power()
            current = ina.get_current()
            print(f"Bus Voltage: {bus_v:.3f} V | Shunt Voltage: {shunt_v:.3f} V | "
                  f"Power: {power:.3f} mW | Current: {current:.3f} mA")
            time.sleep(1)
    finally:
        ina.close()


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

# HC-SR04 configuration
TRIGGER_PINS = (17, 22, 27)
ECHO_PINS = (18, 23, 24)
MAX_DISTANCE_M = 4.0
SAMPLE_INTERVAL_S = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensors = []
    try:
        for trig, echo in zip(TRIGGER_PINS, ECHO_PINS):
            try:
                sensor = DistanceSensor(
                    echo=echo,
                    trigger=trig,
                    max_distance=MAX_DISTANCE_M,
                )
                sensors.append(sensor)
            except GPIOZeroError as exc:
                print(f"Failed to initialize HC-SR04 on trigger={trig}, echo={echo}: {exc}", file=sys.stderr)
                return
    except GPIOZeroError as exc:
        print(f"Failed to initialize any HC-SR04: {exc}", file=sys.stderr)
        return

    try:
        while _running:
            readings = []
            for sensor in sensors:
                try:
                    distance = sensor.distance
                    if distance is None or distance < 0 or distance > MAX_DISTANCE_M:
                        readings.append("ERROR")
                        continue
                    readings.append(f"{distance * 100:.2f} cm")
                except DeviceClosed:
                    readings.append("ERROR")
                    break
                except GPIOZeroError as exc:
                    readings.append(f"ERROR ({exc})")

            parts = ["HC-SR04 Readings"]
            for r in readings:
                parts.append(r)
            print(" | ".join(parts))
            sys.stdout.flush()

            time.sleep(SAMPLE_INTERVAL_S)
    finally:
        for sensor in sensors:
            try:
                sensor.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

