    signal.signal(signal.SIGTERM, handle_signal)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            bus.write_byte_data(ADXL345_ADDR, REG_POWER_CTL, 0x08)
        except OSError as e:
            print(f"Error: failed to initialize ADXL345 at 0x{ADXL345_ADDR:02X}: {e}", file=sys.stderr)
            sys.exit(1)

        while running:
            try:
                data = bus.read_i2c_block_data(ADXL345_ADDR, REG_DATAX0, 6)
                x = data[0] | (data[1] << 8)
                y = data[2] | (data[3] << 8)
                z = data[4] | (data[5] << 8)
                if x >= 0x8000:
                    x -= 0x10000
                if y >= 0x8000:
                    y -= 0x10000
                if z >= 0x8000:
                    z -= 0x10000
                print(f"x={x:6d}  y={y:6d}  z={z:6d}")
            except OSError as e:
                print(f"Error: I2C read failed: {e}", file=sys.stderr)
                sys.exit(1)
            time.sleep(1)
    finally:
        if bus is not None:
            bus.close()

if __name__ == "__main__":
    main()

import time
import signal
import sys
import board
import adafruit_dht

DHT_PIN = board.D4
READ_INTERVAL = 5.0
NUM_READINGS = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = None
    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on GPIO 4: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not _running:
                print("Interrupted by signal.", file=sys.stderr)
                break

            try:
                temperature = sensor.temperature
                humidity = sensor.humidity

                if temperature is None or humidity is None:
                    print(f"Reading {i + 1}: No data returned.", file=sys.stderr)
                else:
                    print(f"Reading {i + 1}: {temperature:.1f} C, {humidity:.1f} %")
            except RuntimeError as exc:
                # DHT22 checksum or timing errors are common; reject and continue.
                print(f"Reading {i + 1}: Error reading DHT22: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Reading {i + 1}: Unexpected error: {exc}", file=sys.stderr)

            if i < NUM_READINGS - 1 and _running:
                time.sleep(READ_INTERVAL)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

import signal
import sys
import time

import board
import adafruit_dht

DHT_PIN = board.D4
NUM_CYCLES = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = None
    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)

        for i in range(NUM_CYCLES):
            if not _running:
                break

            try:
                temperature = sensor.temperature
                humidity = sensor.humidity

                if temperature is not None and humidity is not None:
                    print(f"Cycle {i + 1}: Temp = {temperature:.1f} C, Humidity = {humidity:.1f} %")
                else:
                    print(f"Cycle {i + 1}: Sensor returned None (temperature={temperature}, humidity={humidity})")

            except RuntimeError as e:
                print(f"Cycle {i + 1}: Sensor read error: {e}")
            except Exception as e:
                print(f"Cycle {i + 1}: Unexpected error: {e}")

            if i < NUM_CYCLES - 1 and _running:
                time.sleep(2.0)

    except Exception as e:
        print(f"Initialization error: {e}")
        sys.exit(1)
    finally:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
        print("Program finished.")

if __name__ == "__main__":
    main()
